function perfilCall(PDO $pdo, string $procedure, array $params = []): array { if (str_contains($procedure, 'sp_crud_select') && str_contains($procedure, 'NULL,25')) { $f = json_decode((string)($_GET['filtros'] ?? '{}'), true); if (isset($params['filtros']) && is_array($f)) $params['filtros'] = perfilJson($f); $procedure = str_replace('NULL,25', ':busca,25', $procedure); $params['busca'] = trim((string)($_GET['busca'] ?? '')); } $statement = $pdo->prepare($procedure); $statement->execute($params); $result = $statement->fetchAll(); $statement->closeCursor(); return $result; }
function perfilJson(mixed $value): string { if (is_array($value) && (($value['status'] ?? '') === 'SOLICITADA')) { $value['filtros'] = json_encode((array)json_decode((string)($_POST['filtros'] ?? '{}'), true), JSON_UNESCAPED_UNICODE); $value['busca'] = trim((string)($_POST['busca'] ?? '')); $value['colunas'] = trim((string)($_POST['colunas'] ?? '[]')) ?: '[]'; } return json_encode($value, JSON_UNESCAPED_UNICODE | JSON_UNESCAPED_SLASHES); }
/** 18/11/2026 (pedido do usuário): o código do perfil saiu do grid; perfil novo recebe o código gerado pelo nome (único). */
function perfilCodigoNovo(PDO $pdo, string $nome, array &$usados): string
{
    $mapa = ['Á'=>'A','À'=>'A','Â'=>'A','Ã'=>'A','Ä'=>'A','É'=>'E','È'=>'E','Ê'=>'E','Ë'=>'E','Í'=>'I','Ì'=>'I','Î'=>'I','Ï'=>'I','Ó'=>'O','Ò'=>'O','Ô'=>'O','Õ'=>'O','Ö'=>'O','Ú'=>'U','Ù'=>'U','Û'=>'U','Ü'=>'U','Ç'=>'C','Ñ'=>'N'];
    $base = trim((string)preg_replace('/[^A-Z0-9]+/', '_', strtr(mb_strtoupper(trim($nome), 'UTF-8'), $mapa)), '_');
    $base = mb_substr($base !== '' ? $base : 'PERFIL', 0, 40);
    for ($i = 1; $i < 1000; $i++) {
        $codigo = $i === 1 ? $base : mb_substr($base, 0, 36) . '_' . $i;
        if (isset($usados[$codigo])) continue;
        if (perfilCall($pdo, 'CALL sp_crud_select(:tabela,:filtros,NULL,1,0)', ['tabela' => 'vw_perfis_grid', 'filtros' => perfilJson(['codigo' => $codigo])])) continue;
        $usados[$codigo] = true;
        return $codigo;
    }
    return $base . '_' . time();
}
